CREATE INDEX IX_Books_Id
ON Books (Id);

-- For filtered + paginated queries
CREATE INDEX IX_Books_Genre_Id
ON Books (Genre, Id);

[Query]
[UsePaging]
public IQueryable<Book> GetBooks(
    int? lastId,
    [Service] AppDbContext db)
{
    var query = db.Books.AsQueryable();

    if (lastId.HasValue)
        query = query.Where(b => b.Id > lastId.Value);

    return query.OrderBy(b => b.Id);
}

[Query]
[UseProjection]
[UsePaging]
public IQueryable<Book> GetBooks([Service] AppDbContext db)
{
    return db.Books.Include(b => b.Author);
}
